using Godot;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ActorInspectorOperations
{
    public void assign_transformation_asset(Control owner,Resource actor,Resource property,string path){_batch.edit(Ui<RefCounted>(owner,"property_batch"),actor,property.Get("id").AsStringName(),path);owner.CallDeferred("_rebuild_selected");}
    public void add_transformation_editor(Control owner,Resource property,Resource definition,VBoxContainer parent)
    {
        var actor=Ui<Resource>(owner,"_actor");add_label(parent,property.Get("label").AsString());var row=new HBoxContainer();parent.AddChild(row);string source=_states.source_path(actor);var slot=new ActorResourceSlot();slot.Name="TransformationAsset";slot.Text=source.Length==0?"Load asset…":source.GetFile();slot.TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis;slot.TooltipText=source;slot.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;owner.Call("_configure_file_slot_validation",slot,property);row.AddChild(slot);slot.Connect("file_dropped",Callable.From<string>(path=>assign_transformation_asset(owner,actor,property,path)));slot.Pressed+=()=>owner.Call("_pick_transformation_asset",actor,property);var clear=new Button{Text="×",TooltipText="Clear transformation asset",Disabled=source.Length==0};row.AddChild(clear);clear.Pressed+=()=>assign_transformation_asset(owner,actor,property,"");var assets=ActorTransformationStates.Assets;var asset=_states.load_asset(assets,actor);var document=asset["document"].As<Resource>();if(document==null){add_label(parent,asset["error"].ToString());return;}var edit=new Button{Text="Edit transformation ↗",Name="OpenTransformationWorkspace"};parent.AddChild(edit);edit.Pressed+=()=>owner.GetTree().GetFirstNodeInGroup("actor_scene_tabs")?.Call("open_transformation",_states.source_path(actor));var model=Ui<RefCounted>(owner,"model");foreach(var value in document.Get("components").AsGodotArray()){var item=value.As<Resource>();string id=item.Get("id").AsString();var heading=new HBoxContainer();parent.AddChild(heading);heading.AddChild(new Label{Text=item.Get("title").AsString()+" · Current state",TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});add_keyframe_button(owner,heading,actor,_states.property_for(item),_states.path_for(id),item.Get("default_state_id"));var reset=new Button{Text="↺",TooltipText="Use the default state, or the asset's animation. Scene keyframes still override it."};heading.AddChild(reset);reset.Pressed+=()=>{var states=actor.Get("values").AsGodotDictionary().GetValueOrDefault("component_states",new Settings()).AsGodotDictionary().Duplicate();states.Remove(id);_timeline.edit_property(model,actor,definition,"component_states",states);};var choose=new OptionButton{Name="TransformationState_"+id,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,FitToLongestItem=false};parent.AddChild(choose);foreach(var entry in item.Get("states").AsGodotArray()){var state=entry.As<Resource>();choose.AddItem(state.Get("title").AsString());choose.SetItemMetadata(choose.ItemCount-1,state.Get("id"));}choose.ItemSelected+=index=>{if(!owner.Get("_syncing").AsBool())_states.choose(model,actor,item,choose.GetItemMetadata((int)index).ToString());};void Update(){var clip=_timeline.clip_for_actor_id(model,actor.Get("id").AsString());string selected=_states.current(actor,item,clip!=null?_clips.local_time(clip,model.Get("playhead_time").AsDouble()):0);reset.Visible=actor.Get("values").AsGodotDictionary().GetValueOrDefault("component_states",new Settings()).AsGodotDictionary().ContainsKey(id);for(int i=0;i<choose.ItemCount;i++)if(choose.GetItemMetadata(i).ToString()==selected){choose.Select(i);break;}}Update();owner.Get("_updaters").AsGodotArray().Add(Callable.From(Update));}
    }
    public void setup(Control owner,RefCounted model,RefCounted registry,Resource? state)
    {
        owner.Set("model",model);owner.Set("registry",registry);var batch=Ui<RefCounted>(owner,"property_batch");batch.Set("model",model);batch.Set("registry",registry);state??=new ActorInspectorState();owner.Set("ui_state",state);owner.CustomMinimumSize=new Vector2(220,owner.CustomMinimumSize.Y);owner.ClipContents=true;owner.AddThemeConstantOverride("separation",6);build_navigation(owner);var fields=Ui<VBoxContainer>(owner,"fields");fields.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;fields.AddThemeConstantOverride("separation",6);Ui<ScrollContainer>(owner,"content_scroll").AddChild(fields);model.Connect("changed",new Callable(owner,"refresh"));model.Connect("selection_requested",new Callable(owner,"_selection_requested"));Ui<ScrollContainer>(owner,"content_scroll").GetVScrollBar().Connect("value_changed",new Callable(owner,"_scroll_changed"));state.Connect("changed",new Callable(owner,"_emit_ui_state_changed"));refresh(owner);
    }
    public void selection_requested(Control owner){if(!owner.Get("_inspecting_file").AsBool())return;owner.Set("_inspecting_file",false);owner.Set("_actor",default(Variant));clear_fields(owner);}
}
